def _build_finding_block(f: "ReviewFinding") -> str | None:
    """Build a feedback block for a single red-team finding, or None if non-blocker."""
    if getattr(f, "severity", None) != "blocker":
        return None
    tid = getattr(f, "task_id", None)
    if not tid:
        return None
    parts = [f"- [RED-TEAM {getattr(f, 'severity', 'blocker')}] {getattr(f, 'message', '')}"]
