    if getattr(f, "suggestion", None):
        parts.append(f"  fix: {f.suggestion}")
    return "\n".join(parts)


def _feedback_from_audit_risks(
    audit: "AuditResult", existing: dict[str, list[str]]
) -> dict[str, list[str]]:
    """Process Critical/High risks from an audit into the feedback map."""
    out: dict[str, list[str]] = {}
    risks = getattr(audit, "risks", None) or []
    for r in risks:
        block = _build_risk_block(r, existing)
        if block is not None:
            tid = r.task_id  # type: ignore[attr-defined]
            out.setdefault(tid, []).append(block)
    return out


def _build_risk_block(r: "AuditRisk", existing: dict[str, list[str]]) -> str | None:
    """Build a feedback block for a single risk, or None if not Critical/High or already covered."""
    if getattr(r, "severity", None) not in ("Critical", "High"):
        return None
    tid = getattr(r, "task_id", None)
    if not tid or tid in existing:
        return None
    block = f"- [RED-TEAM {getattr(r, 'severity', 'risk')}] {getattr(r, 'description', '')}"
    if getattr(r, "mitigation", None):
        block += f"\n  fix: {r.mitigation}"
    return block


def _feedback_from_audit(
    findings: list["ReviewFinding"],     audit: "AuditResult"
) -> dict[str, str]:
    """R1 (baziforecaster-nw9ov): render red-team augmented findings + risks into a
    task_id -> prior-feedback text map for the rerun coder brief."""
    findings_out = _feedback_from_audit_findings(findings)
    risks_out = _feedback_from_audit_risks(audit, findings_out)
    # Merge risks into findings output
    for tid, blocks in risks_out.items():
        findings_out.setdefault(tid, []).extend(blocks)
    return {tid: "\n".join(blocks) for tid, blocks in findings_out.items()}"}

